from collections import defaultdict, deque


class Graph:
    """简单图基础类: 支持有向/无向, 邻接表存储
    提供度数计算、连通块计数、环检测等基础操作
    """
    def __init__(self, n, directed=False):
        self.n = n
        self.directed = directed
        self.adj = defaultdict(list)

    def add_edge(self, u, v):
        self.adj[u].append(v)
        if not self.directed:
            self.adj[v].append(u)

    def degree(self, u):
        """返回节点 u 的度(无向)或出度(有向)"""
        return len(self.adj[u])

    def in_degree(self, u):
        """返回节点 u 的入度(仅对有向图有意义)"""
        cnt = 0
        for v in range(self.n):
            for w in self.adj[v]:
                if w == u:
                    cnt += 1
        return cnt

    def connected_components(self):
        """求无向图连通块数量 (BFS)"""
        visited = [False] * self.n
        count = 0
        for start in range(self.n):
            if not visited[start]:
                count += 1
                q = deque([start])
                visited[start] = True
                while q:
                    u = q.popleft()
                    for v in self.adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            q.append(v)
        return count

    def has_path(self, s, t):
        """检查 s 到 t 是否存在路径 (BFS)"""
        visited = [False] * self.n
        q = deque([s])
        visited[s] = True
        while q:
            u = q.popleft()
            if u == t:
                return True
            for v in self.adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        return False

    def handshake_check(self):
        """验证握手定理: sum(deg) == 2*|E| (无向图)"""
        total = sum(self.degree(u) for u in range(self.n))
        edge_count = sum(len(self.adj[u]) for u in range(self.n))
        if not self.directed:
            return total == 2 * edge_count // 2 * 2 and total == edge_count
        return total == edge_count  # 有向图 sum(out) = |E|


if __name__ == "__main__":
    # 无向图: 0-1, 1-2, 3-4 (两个连通块)
    g = Graph(5, directed=False)
    g.add_edge(0, 1)
    g.add_edge(1, 2)
    g.add_edge(3, 4)

    assert g.connected_components() == 2
    assert g.degree(1) == 2
    assert g.has_path(0, 2) == True
    assert g.has_path(0, 4) == False

    # 有向图: 0->1->2->0 (环)
    dg = Graph(3, directed=True)
    dg.add_edge(0, 1)
    dg.add_edge(1, 2)
    dg.add_edge(2, 0)
    assert dg.degree(0) == 1   # 出度
    assert dg.in_degree(0) == 1
    assert dg.has_path(0, 2) == True

    print("All tests passed.")
